import { band, MOTIF_NAMES } from './ornament-source.mjs';
import { writeFileSync } from 'node:fs';

const inner = (n) => band(n)
  .replace(/^<svg[^>]*>/, '')
  .replace(/<\/svg>$/, '')
  .replace(/stroke-width=/g, 'stroke-width=')      // kept: raw markup, not JSX
  .replace(/"/g, '\\"');

const entries = MOTIF_NAMES.map((n) => `  ${n}:\n    "${inner(n)}",`).join('\n');

writeFileSync(new URL('../src/components/ui/OrnamentBand.tsx', import.meta.url), `/* eslint-disable */
/**
 * Khmer ornament bands — generated by scripts/ornament-source.mjs.
 *
 * Each band is a crowned centre motif with symmetric kbach vines, a hairline
 * rule punctuated by diamonds, and a corner cluster at either end. Half is
 * drawn and mirrored about the centre, so the result is exactly symmetric.
 *
 * The markup is a build artefact of that script, not hand-authored, so it is
 * injected as static SVG rather than transcribed into JSX.
 */
export type BandMotif = ${MOTIF_NAMES.map((n) => `"${n}"`).join(" | ")};

export const BAND_MOTIFS: BandMotif[] = [${MOTIF_NAMES.map((n) => `"${n}"`).join(", ")}];

export function OrnamentBand({
  motif = "lotus",
  className = "",
  flip = false,
}: {
  motif?: BandMotif;
  className?: string;
  /** Mirrors the band vertically, for the foot of the card. */
  flip?: boolean;
}) {
  return (
    <svg
      viewBox="0 0 1000 190"
      preserveAspectRatio="xMidYMid meet"
      className={\`\${flip ? "-scale-y-100" : ""} \${className}\`}
      fill="none"
      aria-hidden="true"
      dangerouslySetInnerHTML={{ __html: BANDS[motif] ?? BANDS.lotus }}
    />
  );
}

const BANDS: Record<string, string> = {
${entries}
};
`);
console.log('emitted', MOTIF_NAMES.join(', '));
